IS_WINDOWS = sys.platform == "win32"

if IS_WINDOWS:
    try:
        user32 = ctypes.windll.user32
        kernel32 = ctypes.windll.kernel32
        gdiplus_dll = ctypes.windll.gdiplus
    except Exception:
        user32 = kernel32 = gdiplus_dll = None
else:
    user32 = kernel32 = gdiplus_dll = None

CALLBACK = ctypes.WINFUNCTYPE if IS_WINDOWS else ctypes.CFUNCTYPE

# Windows constants ---------------------------------------------------------
WH_KEYBOARD_LL = 13
WH_MOUSE_LL = 14
WM_KEYDOWN = 0x0100
WM_KEYUP = 0x0101
WM_SYSKEYDOWN = 0x0104
WM_SYSKEYUP = 0x0105
HC_ACTION = 0

VK_BACK = 0x08
VK_TAB = 0x09
VK_RETURN = 0x0D
VK_SHIFT = 0x10
VK_CONTROL = 0x11
VK_MENU = 0x12
VK_CAPITAL = 0x14
VK_ESCAPE = 0x1B
VK_SPACE = 0x20
VK_PRIOR = 0x21
VK_NEXT = 0x22
VK_END = 0x23
VK_HOME = 0x24
VK_LEFT = 0x25
VK_UP = 0x26
VK_RIGHT = 0x27
VK_DOWN = 0x28
VK_SNAPSHOT = 0x2C
VK_INSERT = 0x2D
VK_DELETE = 0x2E
VK_LWIN = 0x5B
VK_RWIN = 0x5C
VK_APPS = 0x5D
VK_LSHIFT = 0xA0
VK_RSHIFT = 0xA1
VK_NUMPAD0 = 0x60
VK_NUMPAD9 = 0x69
VK_F1 = 0x70
VK_F24 = 0x87
VK_CLEAR = 0x0C
VK_PAUSE = 0x13
VK_NUMLOCK = 0x90
VK_SCROLL = 0x91
VK_BROWSER_BACK = 0xA6
VK_VOLUME_MUTE = 0xAD
VK_VOLUME_DOWN = 0xAE
VK_VOLUME_UP = 0xAF
VK_MEDIA_PLAY_PAUSE = 0xB3
VK_LAUNCH_MAIL = 0xB4
SW_HIDE = 0
SW_SHOW = 5
SWP_NOSIZE = 0x0001
SWP_NOMOVE = 0x0002
SWP_NOACTIVATE = 0x0010
SWP_SHOWWINDOW = 0x0040
HWND_TOPMOST = -1
GA_ROOT = 2
MONITOR_DEFAULTTOPRIMARY = 1
MONITORINFOF_PRIMARY = 1
SM_XVIRTUALSCREEN = 76
SM_YVIRTUALSCREEN = 77
SM_CXVIRTUALSCREEN = 78
SM_CYVIRTUALSCREEN = 79
VK_CONTROL_STATE = 0x8000
DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2 = -4

# Windows accessibility hotkey activation bits.  These changes are made
# for the current session only: fWinIni is 0, so the stored defaults in the
# registry are not rewritten.
SPI_GETFILTERKEYS = 0x0032
SPI_SETFILTERKEYS = 0x0033
SPI_GETTOGGLEKEYS = 0x0034
SPI_SETTOGGLEKEYS = 0x0035
SPI_GETSTICKYKEYS = 0x003A
SPI_SETSTICKYKEYS = 0x003B
SKF_HOTKEYACTIVE = 0x00000004
FKF_HOTKEYACTIVE = 0x00000004
TKF_HOTKEYACTIVE = 0x00000004


class RECT(ctypes.Structure):
    _fields_ = [("left", ctypes.c_int32), ("top", ctypes.c_int32),
                ("right", ctypes.c_int32), ("bottom", ctypes.c_int32)]


class MONITORINFO(ctypes.Structure):
    _fields_ = [("cbSize", ctypes.c_uint32),
                ("rcMonitor", RECT), ("rcWork", RECT),
                ("dwFlags", ctypes.c_uint32)]


class STICKYKEYS(ctypes.Structure):
    _fields_ = [("cbSize", ctypes.c_uint32),
                ("dwFlags", ctypes.c_uint32)]


class TOGGLEKEYS(ctypes.Structure):
    _fields_ = [("cbSize", ctypes.c_uint32),
                ("dwFlags", ctypes.c_uint32)]


class FILTERKEYS(ctypes.Structure):
    _fields_ = [("cbSize", ctypes.c_uint32),
                ("dwFlags", ctypes.c_uint32),
                ("iWaitMSec", ctypes.c_uint32),
                ("iDelayMSec", ctypes.c_uint32),
                ("iRepeatMSec", ctypes.c_uint32),
                ("iBounceMSec", ctypes.c_uint32)]


class KBDLLHOOKSTRUCT(ctypes.Structure):
    _fields_ = [("vkCode", ctypes.c_uint32),
                ("scanCode", ctypes.c_uint32),
                ("flags", ctypes.c_uint32),
                ("time", ctypes.c_uint32),
                ("dwExtraInfo", ctypes.c_size_t)]


class Monitor:
    __slots__ = ("x", "y", "w", "h", "primary")

    def __init__(self, x, y, w, h, primary):
        self.x = int(x)
        self.y = int(y)
        self.w = max(1, int(w))
        self.h = max(1, int(h))
        self.primary = bool(primary)

    def __repr__(self):
        return "Monitor(%d,%d,%dx%d,primary=%r)" % (
            self.x, self.y, self.w, self.h, self.primary)


def clamp(value, low, high):
    return low if value < low else high if value > high else value


def set_dpi_awareness():
    """Use physical pixels so monitor rectangles are exact."""
    if not IS_WINDOWS or user32 is None:
        return
    try:
        user32.SetProcessDpiAwarenessContext.argtypes = [ctypes.c_void_p]
        user32.SetProcessDpiAwarenessContext.restype = ctypes.c_int
        if user32.SetProcessDpiAwarenessContext(
                ctypes.c_void_p(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2)):
            return
    except Exception:
        pass
    try:
        user32.SetProcessDPIAware()
    except Exception:
        pass


def enum_monitors():
    if not IS_WINDOWS or user32 is None:
        return [Monitor(0, 0, 1920, 1080, True)]

    monitors = []
    proc_type = CALLBACK(ctypes.c_int, ctypes.c_void_p, ctypes.c_void_p,
                         ctypes.POINTER(RECT), ctypes.c_size_t)

    def callback(hmonitor, hdc, lprect, lparam):
        info = MONITORINFO()
        info.cbSize = ctypes.sizeof(info)
        if user32.GetMonitorInfoW(hmonitor, ctypes.byref(info)):
            r = info.rcMonitor
            monitors.append(Monitor(r.left, r.top,
                                    r.right - r.left, r.bottom - r.top,
                                    bool(info.dwFlags & MONITORINFOF_PRIMARY)))
        return 1

    proc = proc_type(callback)
    try:
        user32.EnumDisplayMonitors(None, None, proc, 0)
    except Exception:
        pass
    if not monitors:
        try:
            w = user32.GetSystemMetrics(0)
            h = user32.GetSystemMetrics(1)
        except Exception:
            w, h = 1920, 1080
        monitors = [Monitor(0, 0, w, h, True)]
    if not any(m.primary for m in monitors):
        monitors[0].primary = True
    return monitors


def virtual_rect():
    if not IS_WINDOWS or user32 is None:
        return (0, 0, 1920, 1080)
    try:
        x = int(user32.GetSystemMetrics(SM_XVIRTUALSCREEN))
        y = int(user32.GetSystemMetrics(SM_YVIRTUALSCREEN))
        w = int(user32.GetSystemMetrics(SM_CXVIRTUALSCREEN))
        h = int(user32.GetSystemMetrics(SM_CYVIRTUALSCREEN))
        if w > 0 and h > 0:
            return (x, y, w, h)
    except Exception:
        pass
    return (0, 0, 1920, 1080)


def top_hwnd(window):
    if not IS_WINDOWS or user32 is None:
        return 0
    try:
        child = int(window.winfo_id())
    except Exception:
        return 0
    try:
        parent = user32.GetParent(child)
        if parent:
            return int(parent)
    except Exception:
        pass
    try:
        root = user32.GetAncestor(child, GA_ROOT)
        if root:
            return int(root)
    except Exception:
        pass
    return child


def set_window_pos(hwnd, x, y, w, h, topmost=True, activate=False):
    if not IS_WINDOWS or user32 is None or not hwnd:
        return
    flags = SWP_SHOWWINDOW
    if not activate:
        flags |= SWP_NOACTIVATE
    try:
        user32.SetWindowPos(ctypes.c_void_p(hwnd),
                            ctypes.c_void_p(HWND_TOPMOST if topmost else 0),
                            int(x), int(y), int(w), int(h), flags)
    except Exception:
        pass


def bring_to_front(hwnd):
    if not IS_WINDOWS or user32 is None or not hwnd:
        return
    try:
        user32.ShowWindow(ctypes.c_void_p(hwnd), SW_SHOW)
        user32.BringWindowToTop(ctypes.c_void_p(hwnd))
        user32.SetForegroundWindow(ctypes.c_void_p(hwnd))
    except Exception:
        pass


def set_topmost(hwnd):
    if not IS_WINDOWS or user32 is None or not hwnd:
        return
    try:
        user32.SetWindowPos(ctypes.c_void_p(hwnd), ctypes.c_void_p(HWND_TOPMOST),
                            0, 0, 0, 0,
                            SWP_NOMOVE | SWP_NOSIZE | SWP_NOACTIVATE)
    except Exception:
        pass


def clip_cursor_to_virtual_screen():
    if not IS_WINDOWS or user32 is None:
        return
    x, y, w, h = virtual_rect()
    r = RECT(x, y, x + w, y + h)
    try:
        user32.ClipCursor(ctypes.byref(r))
    except Exception:
        pass


def unclip_cursor():
    if not IS_WINDOWS or user32 is None:
        return
    try:
        user32.ClipCursor(None)
    except Exception:
        pass


def hide_pointer():
    """Keep the system pointer invisible while the prank is in front."""
    if not IS_WINDOWS or user32 is None:
        return
    try:
        user32.SetCursor(None)
    except Exception:
        pass


def restore_pointer():
    if not IS_WINDOWS or user32 is None:
        return
    try:
        user32.LoadCursorW.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
        user32.LoadCursorW.restype = ctypes.c_void_p
        arrow = user32.LoadCursorW(None, ctypes.c_void_p(32512))
        if arrow:
            user32.SetCursor(ctypes.c_void_p(arrow))
    except Exception:
        pass


def hide_console():
    if not IS_WINDOWS or kernel32 is None or user32 is None:
        return
    try:
        hwnd = kernel32.GetConsoleWindow()
        if hwnd:
            user32.ShowWindow(ctypes.c_void_p(hwnd), SW_HIDE)
    except Exception:
        pass


def show_error_box(message):
    if IS_WINDOWS and user32 is not None:
        try:
            user32.MessageBoxW(None, str(message), "BossDefender", 0x10)
            return
        except Exception:
            pass
    try:
        sys.stderr.write(str(message) + "\n")
    except Exception:
        pass


def modifier_down():
    """True while Ctrl, Alt or a Windows key is physically held."""
    if not IS_WINDOWS or user32 is None:
        return False
    for vk in (VK_CONTROL, VK_MENU, VK_LWIN, VK_RWIN):
        try:
            if user32.GetAsyncKeyState(vk) & VK_CONTROL_STATE:
                return True
        except Exception:
            pass
    return False


# ---------------------------------------------------------------------------
# Exact keyboard allow-list from fake_ransom.cs
# ---------------------------------------------------------------------------

def is_allowed_vk(vk):
    vk = int(vk) & 0xFF
    if 0x41 <= vk <= 0x5A:          # A-Z
        return True
    if 0x30 <= vk <= 0x39:          # 0-9 (top row)
        return True
    if VK_NUMPAD0 <= vk <= VK_NUMPAD9:
        return True
    if vk in (VK_BACK, VK_RETURN, VK_SHIFT, VK_LSHIFT, VK_RSHIFT):
        return True
    return False


class AccessibilityGuard:
    """Temporarily clear the Shift/NumLock accessibility hotkey bits.

    The keyboard hook must let Shift and NumLock through.  Windows can turn
    those allowed keys into Sticky Keys (five Shift taps), Filter Keys (hold
    right Shift) or Toggle Keys (hold NumLock) shortcuts.  Clearing only the
    HOTKEYACTIVE bits keeps the accessibility features themselves untouched;
    it just stops those key-only activation shortcuts.
    """

    def __init__(self, debug=False):
        self.debug = debug
        self.saved = []

    @staticmethod
    def _prepare():
        if not IS_WINDOWS or user32 is None:
            return False
        try:
            user32.SystemParametersInfoW.argtypes = [
                ctypes.c_uint, ctypes.c_uint, ctypes.c_void_p,
                ctypes.c_uint]
            user32.SystemParametersInfoW.restype = ctypes.c_int
            return True
        except Exception:
            return False

    def _disable_one(self, label, get_action, set_action, struct_type,
                     hotkey_bit):
        value = struct_type()
        value.cbSize = ctypes.sizeof(value)
        try:
            if not user32.SystemParametersInfoW(
                    get_action, ctypes.sizeof(value),
                    ctypes.byref(value), 0):
                return
        except Exception:
            return
        original = struct_type.from_buffer_copy(value)
        self.saved.append((set_action, original))
        if not (original.dwFlags & hotkey_bit):
            return
        value.dwFlags = original.dwFlags & ~hotkey_bit
        try:
            user32.SystemParametersInfoW(
                set_action, ctypes.sizeof(value), ctypes.byref(value), 0)
            if self.debug:
                print("accessibility hotkey disabled:", label,
                      file=sys.stderr)
        except Exception:
            pass

    def disable(self):
        if not self._prepare():
            return False
        self._disable_one("Sticky Keys", SPI_GETSTICKYKEYS,
                          SPI_SETSTICKYKEYS, STICKYKEYS, SKF_HOTKEYACTIVE)
        self._disable_one("Filter Keys", SPI_GETFILTERKEYS,
                          SPI_SETFILTERKEYS, FILTERKEYS, FKF_HOTKEYACTIVE)
        self._disable_one("Toggle Keys", SPI_GETTOGGLEKEYS,
                          SPI_SETTOGGLEKEYS, TOGGLEKEYS, TKF_HOTKEYACTIVE)
        return bool(self.saved)

    def restore(self):
        if not self.saved:
            return
        if not self._prepare():
            return
        for set_action, original in reversed(self.saved):
            try:
                user32.SystemParametersInfoW(
                    set_action, ctypes.sizeof(original),
                    ctypes.byref(original), 0)
            except Exception:
                pass
        self.saved = []
        if self.debug:
            print("accessibility hotkeys restored", file=sys.stderr)


class KeyboardBlocker:
    """A WH_KEYBOARD_LL hook that returns 1 for every non-allowed key."""

    def __init__(self, debug=False):
        self.debug = debug
        self.hook = None
        self.proc = None
        self.blocked = 0
        self.allowed = 0
        self.seen = []
        self._proc_type = CALLBACK(ctypes.c_ssize_t, ctypes.c_int,
                                   ctypes.c_size_t, ctypes.c_ssize_t)

    def install(self):
        if not IS_WINDOWS or user32 is None:
            return False
        try:
            user32.SetWindowsHookExW.argtypes = [
                ctypes.c_int, ctypes.c_void_p, ctypes.c_void_p,
                ctypes.c_uint32]
            user32.SetWindowsHookExW.restype = ctypes.c_void_p
            user32.CallNextHookEx.argtypes = [
                ctypes.c_void_p, ctypes.c_int, ctypes.c_size_t,
                ctypes.c_ssize_t]
            user32.CallNextHookEx.restype = ctypes.c_ssize_t
            user32.UnhookWindowsHookEx.argtypes = [ctypes.c_void_p]
            user32.UnhookWindowsHookEx.restype = ctypes.c_int
            if kernel32 is not None:
                kernel32.GetModuleHandleW.argtypes = [ctypes.c_wchar_p]
                kernel32.GetModuleHandleW.restype = ctypes.c_void_p
                kernel32.GetLastError.restype = ctypes.c_uint32
        except Exception:
            pass

        def callback(ncode, wparam, lparam):
            try:
                if ncode < 0:
                    return user32.CallNextHookEx(self.hook, ncode, wparam,
                                                 lparam)
                info = ctypes.cast(lparam, ctypes.POINTER(KBDLLHOOKSTRUCT))
                vk = int(info.contents.vkCode)
                if self.debug:
                    self.seen.append((vk, int(wparam)))
                    if len(self.seen) > 200:
                        self.seen = self.seen[-100:]
                if is_allowed_vk(vk):
                    self.allowed += 1
                    return user32.CallNextHookEx(self.hook, ncode, wparam,
                                                 lparam)
                self.blocked += 1
                return 1
            except Exception:
                return 1 if ncode >= 0 else 0

        self.proc = self._proc_type(callback)
        proc_ptr = ctypes.cast(self.proc, ctypes.c_void_p)
        try:
            hmod = kernel32.GetModuleHandleW(None) if kernel32 else None
        except Exception:
            hmod = None
        for module in (hmod, None):
            try:
                self.hook = user32.SetWindowsHookExW(
                    WH_KEYBOARD_LL, proc_ptr,
                    ctypes.c_void_p(module or 0), 0)
            except Exception:
                self.hook = None
            if self.hook:
                break
        if not self.hook:
            if self.debug:
                try:
                    err = kernel32.GetLastError() if kernel32 else 0
                except Exception:
                    err = 0
                print("keyboard hook failed (error %s)" % err, file=sys.stderr)
            return False
        if self.debug:
            print("keyboard hook installed", file=sys.stderr)
        return True

    def uninstall(self):
        if self.hook and IS_WINDOWS and user32 is not None:
            try:
                user32.UnhookWindowsHookEx(ctypes.c_void_p(self.hook))
            except Exception:
                pass
        self.hook = None
        self.proc = None


class MouseBlocker:
    """Swallow every global mouse event while the prank is frontmost."""

    def __init__(self, debug=False):
        self.debug = debug
        self.hook = None
